        mapping:['字段映射配置',`${monthLabel(currentMonth)} · 校验直接映射与系统计算字段`],
        results:['计算结果 · 工资明细表',`${monthLabel(currentMonth)} · 7 组字段 · ${employees.length} 人${state.liveImport?'导入':'示例'}数据`],
        slip:['工资条预览',`${monthLabel(currentMonth)} · 按员工查看工资明细`],
        email:['邮件正文校准',`${monthLabel(currentMonth)} · 自动生成特殊事项说明，核对后打开企业微信邮箱`],
